-- ============================================================================
-- BHA location hierarchy seed: Gabon (GA)
-- Source: "Africa Location Hierarchies - Universal Review" - Gabon
-- 325 locations beyond the country root. Idempotent: re-running refreshes.
-- Prerequisite: supabase/migrations/004_location_hierarchy.sql
--
-- NOTE: 3 source name(s) collapse into an existing sibling slug.
-- The first name wins; the duplicate name is not stored as a separate row:
--   gabon/haut-ogooue-province/plateaux-department/leconi  <-- keeps "Léconi", drops duplicate "Leconi"
--   gabon/nyanga-province/mongo-department/moulengui-binza  <-- keeps "Moulengui-Binza", drops duplicate "Mouléngui-Binza"
--   gabon/woleu-ntem-province/haut-como-department/medouneu  <-- keeps "Medouneu", drops duplicate "Médouneu"
-- ============================================================================

-- 0. Country row (adds any territory missing from the base schema seed)
insert into public.countries (code, name) values
  ('GA', 'Gabon')
on conflict (code) do update set name = excluded.name;

-- 1. Country root (level 1)
insert into public.locations (country_code, parent_id, name, location_type, level, path, sort_order)
select 'GA', null, 'Gabon', 'Country', 1, 'gabon', 0
on conflict (country_code, path) do update set
  name = excluded.name, location_type = excluded.location_type, level = excluded.level;

-- 2. Level 2 (9 rows)
insert into public.locations (country_code, parent_id, name, location_type, level, path, sort_order)
select 'GA', p.id, v.name, v.location_type, v.level, v.path, v.sort_order
from (values
    ('gabon', 'Estuaire Province', 'Province', 2, 'gabon/estuaire-province', 0),
    ('gabon', 'Haut-Ogooué Province', 'Province', 2, 'gabon/haut-ogooue-province', 1),
    ('gabon', 'Moyen-Ogooué Province', 'Province', 2, 'gabon/moyen-ogooue-province', 2),
    ('gabon', 'Ngounié Province', 'Province', 2, 'gabon/ngounie-province', 3),
    ('gabon', 'Nyanga Province', 'Province', 2, 'gabon/nyanga-province', 4),
    ('gabon', 'Ogooué-Ivindo Province', 'Province', 2, 'gabon/ogooue-ivindo-province', 5),
    ('gabon', 'Ogooué-Lolo Province', 'Province', 2, 'gabon/ogooue-lolo-province', 6),
    ('gabon', 'Ogooué-Maritime Province', 'Province', 2, 'gabon/ogooue-maritime-province', 7),
    ('gabon', 'Woleu-Ntem Province', 'Province', 2, 'gabon/woleu-ntem-province', 8)
) as v(parent_path, name, location_type, level, path, sort_order)
join public.locations p
  on p.country_code = 'GA' and p.path = v.parent_path
on conflict (country_code, path) do update set
  name = excluded.name, location_type = excluded.location_type, level = excluded.level,
  sort_order = excluded.sort_order, parent_id = excluded.parent_id;

